 def __init__(self):super().__init__();self.stack=[];self.cur=[];self.ps=[]
 def handle_starttag(self,t,a):
  self.stack.append(t)
  if t in ('p','h1','h2','h3'): self.cur=[]
 def handle_data(self,d):
  if any(x in ('p','h1','h2','h3') for x in self.stack):self.cur.append(d)
 def handle_endtag(self,t):
  if t in ('p','h1','h2','h3'):
   x=' '.join(''.join(self.cur).split())
   if x:self.ps.append((t,x))
   self.cur=[]
  if t in self.stack:
   i=len(self.stack)-1-self.stack[::-1].index(t);self.stack=self.stack[:i]
for f in glob.glob('/tmp/*.html'):
 if os.path.basename(f) not in ['racereport.html','lowdown.html','strategy.html','lessons.html','teams.html','ferrari.html']:continue
 p=P();p.feed(open(f).read())
 print('\n\n###',os.path.basename(f),len(p.ps))
 seen=set()
 for tag,x in p.ps:
  if x not in seen:
   seen.add(x);print(tag.upper(),x)
